/// <summary>
///     The <c>KCS_KBVResponsibilitiesTable</c> class is the extension of table <c>common</c>
/// </summary>
public class KCS_KBVResponsibilitiesTable extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>find</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_smmResponsibilityId">
///    <c>smmResponsibilityId</c> as type
/// </param>
/// <param name="_forUpdate">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVResponsibilitiesTable</c> as return value
/// </returns>
static KCS_KBVResponsibilitiesTable find(   KCS_KBVBuildingProjectID    _kcs_KBVBuildingProjectID,
                                            smmResponsibilityId         _smmResponsibilityId,
                                            boolean                     _forUpdate = false)
{
    KCS_KBVResponsibilitiesTable record;

    if (_forUpdate)
    {
        record.selectForUpdate(_forUpdate);
    }

    select firstonly record
    where   record.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
        &&  record.smmResponsibilityId      == _smmResponsibilityId
        &&  record.KCS_KBVCompetenceEndDate == dateNull();

    if(!record.RecId)
    {
        select firstonly record
        order by record.KCS_KBVCompetenceEndDate desc
        where   record.KCS_KBVBuildingProjectID == _kcs_KBVBuildingProjectID
            &&  record.smmResponsibilityId      == _smmResponsibilityId
            &&  record.KCS_KBVCompetenceEndDate != dateNull();
    }

    return record;
}

/// <summary>
///    AVA <c>getHighestResponsibility</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectID">
///    <c>KCS_KBVBuildingProjectID</c> as type
/// </param>
/// <param name="_dataArea">
///    <c>DataAreaId</c> as type
/// </param>
/// <returns>
///    <c>HCMWorkerRecId</c> as return value
/// </returns>
static HCMWorkerRecId getHighestResponsibility( KCS_KBVBuildingProjectID   _kcs_KBVBuildingProjectID,
                                                DataAreaId                 _dataArea)
{
    KCS_KBVResponsibilitiesTable    locKCS_KBVResponsibilitiesTable;
    smmResponsibilityGroup          locsmmResponsibilityGroup;
    HcmWorker                       locHCMWorker;

    container                       locDataAreaIdContainer;
    HCMWorkerRecId                  locHCMWorkerRecId;

    locDataAreaIdContainer = [_dataArea];

    select firstonly crosscompany : locDataAreaIdContainer *
    from    locKCS_KBVResponsibilitiesTable
    order by locsmmResponsibilityGroup.KCS_KBVSalesPriority desc, locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate
    where   locKCS_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID        == _kcs_KBVBuildingProjectID
        &&  (   locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate    == DateNull()
            ||  locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate    >= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())    )
    join    locsmmResponsibilityGroup
    where   locsmmResponsibilityGroup.ResponsibilityId == locKCS_KBVResponsibilitiesTable.smmResponsibilityId
    join    locHCMWorker
    where   locHCMWorker.RecId              == locKCS_KBVResponsibilitiesTable.smmWorker
        &&  locHCMWorker.NDX_KBVActivities  == NoYes::Yes;

    locHCMWorkerRecId       = locKCS_KBVResponsibilitiesTable.smmWorker;

    return locHCMWorkerRecId;
}

/// <summary>
/// N.Freidenberger 24.06.2025
/// </summary>
/// <param name = "_kcs_KBVBuildingProjectID">_kcs_KBVBuildingProjectID</param>
/// <returns>HCMWorkerRecId</returns>
static KCS_KBVResponsibilitiesTable getHighestResponsibilityCrosscompany( KCS_KBVBuildingProjectID   _kcs_KBVBuildingProjectID)
{
    KCS_KBVResponsibilitiesTable    locKCS_KBVResponsibilitiesTable;
    smmResponsibilityGroup          locsmmResponsibilityGroup;
    HcmWorker                       locHCMWorker;
    KCS_KBVCompPrio                 compPrio;

    container                       locDataAreaIdContainer;
    HCMWorkerRecId                  locHCMWorkerRecId;


    select firstonly crosscompany 
        locKCS_KBVResponsibilitiesTable
    order by compPrio.Id asc,  locsmmResponsibilityGroup.KCS_KBVSalesPriority desc, locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate
    where   locKCS_KBVResponsibilitiesTable.KCS_KBVBuildingProjectID        == _kcs_KBVBuildingProjectID
        &&  (   locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate    == DateNull()
            ||  locKCS_KBVResponsibilitiesTable.KCS_KBVCompetenceEndDate    >= DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone())    )
    join    locsmmResponsibilityGroup
    where   locsmmResponsibilityGroup.ResponsibilityId == locKCS_KBVResponsibilitiesTable.smmResponsibilityId
    join    locHCMWorker
    where   locHCMWorker.RecId              == locKCS_KBVResponsibilitiesTable.smmWorker
        &&  locHCMWorker.NDX_KBVActivities  == NoYes::Yes
    join compPrio
        where compPrio.Company == locKCS_KBVResponsibilitiesTable.DataAreaId
           && compPrio.ActivityCompany != '';

    locHCMWorkerRecId       = locKCS_KBVResponsibilitiesTable.smmWorker;

    return locKCS_KBVResponsibilitiesTable;
}

/// <summary>
///    AVA <c>activityAvail</c> method.
/// </summary>
/// <param name="_kcs_KBVBuildingProjectRecId">
///    <c>RecId</c> as type
/// </param>
/// <param name="_hcm_WorkerRecId">
///    <c>HcmWorkerRecId</c> as type
/// </param>
/// <param name="_dataArea">
///    <c>DataAreaId</c> as type
/// </param>
/// <returns>
///    <c>smmActivities</c> as return value
/// </returns>
static smmActivities activityAvail( RecId           _kcs_KBVBuildingProjectRecId, 
                                    HcmWorkerRecId  _hcm_WorkerRecId,
                                    DataAreaId      _dataArea                       = '')
{
    //  checks if there is allready an activity
    //  if function is called without a dataarea it searches in all bp-companies
    smmActivityParentLinkTable  smmActivityParentLinkTable;
    smmActivities               smmActivities;
    KCS_KBVParameters           kcs_KBVParameters;
    container                   cDataAreaId;

    if (!_dataArea)
    {
        cDataAreaId = AVAKBVBuildingProjectHelper::getAllBPCompanies();
    }
    else
    {
        cDataAreaId = [_dataArea];
    }

    kcs_KBVParameters = KCS_KBVParameters::find();
    if (kcs_KBVParameters.RecId)
    {
        select firstOnly1 crosscompany : cDataAreaId *
        from    smmActivityParentLinkTable
            where   smmActivityParentLinkTable.ParentType   == smmActivityParentType::BuildingProject
                &&  smmActivityParentLinkTable.RefRecId     == _kcs_KBVBuildingProjectRecId
            join *
            from    smmActivities
            where   smmActivities.ActivityNumber        == smmActivityParentLinkTable.ActivityNumber
                &&  smmActivities.Category              == kcs_KBVParameters.KCS_KBVActivityCategory
                &&  smmActivities.TypeId                == kcs_KBVParameters.KCS_KBVActivityTypeId
                //&&  smmActivities.ResponsibleEmployee   == _emplId;
                &&  smmActivities.ResponsibleWorker     == _hcm_WorkerRecId;
    }

    return smmActivities;
}

/// <summary>
///    AVA <c>displayKCS_KBVSalesPriority</c> method.
/// </summary>
/// <returns>
///    <c>KCS_KBVSalesPriority</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display KCS_KBVSalesPriority displayKCS_KBVSalesPriority()
{
    KCS_KBVSalesPriority    retVal;

    smmResponsibilityGroup  locBuffer;

    select firstonly locBuffer
        where   locBuffer.KCS_KBVsmmRespGroupIsBV   == NoYes::Yes
        &&  locBuffer.ResponsibilityId              == this.smmResponsibilityId;

    retVal =  locBuffer.KCS_KBVSalesPriority;

    return retVal;
}
